UPDATE comtnemplyrinfo
   SET last_login_dt = now(), fail_cnt = 0
 WHERE emplyr_id = #{emplyrId}

UPDATE comtnemplyrinfo
   SET fail_cnt = fail_cnt + 1,
       lock_at = CASE WHEN #{threshold} > 0 AND fail_cnt + 1 >= #{threshold}
                      THEN 'Y' ELSE lock_at END
 WHERE emplyr_id = #{emplyrId}
